    let main_points: Vec<(f64, f64)> = main
        .freq
        .iter()
        .zip(main.spl.iter())
        .map(|(&freq, &spl)| (freq, spl))
        .collect();
    let sub_points: Vec<(f64, f64)> = sub
        .freq
        .iter()
        .zip(sub.spl.iter())
        .map(|(&freq, &spl)| (freq, spl))
        .collect();
    let main_phase = room_eq_phase_points(main);
    let sub_phase = room_eq_phase_points(sub);
    let points = sum_room_eq_responses_db(
        &main_points,
        &sub_points,
        main_phase.as_deref(),
        sub_phase.as_deref(),
    );
